100	          <label>隐私参数 ε（0.1–1.0）<input id="epsilon" type="number" min="0.1" max="1.0" step="0.1" value="0.5" required></label>
101	          <label>区域 region<input id="filter-region" placeholder="如 north，可留空"></label>
