206	  <script>
207	    const FILTER_FIELDS = ['region', 'membership', 'age_band', 'visit_bucket'];
208	
209	    function newRequestId() {
210	      const suffix = crypto.randomUUID ? crypto.randomUUID().slice(0, 8) : String(Date.now());
211	      return `req-${suffix}`;
212	    }
213	
214	    async function loadCatalog() {
215	      const status = document.getElementById('status');
216	      const list = document.getElementById('datasets');
217	      try {
218	        const response = await fetch('/api/datasets');
219	        if (!response.ok) throw new Error(`HTTP ${response.status}`);
220	        const datasets = await response.json();
221	        status.textContent = `可用数据集 · ${datasets.length}`;
222	        for (const dataset of datasets) {
223	          const card = document.createElement('article');
224	          const title = document.createElement('h2');
225	          title.textContent = dataset.name;
226	          const description = document.createElement('p');
227	          description.textContent = dataset.description;
228	          const badge = document.createElement('span');
229	          badge.className = 'badge';
230	          badge.textContent = dataset.synthetic ? '合成数据' : '本地数据';
231	          const fields = document.createElement('div');
232	          fields.className = 'fields';
233	          for (const name of dataset.fields) {
234	            const field = document.createElement('code');
235	            field.textContent = name;
236	            fields.append(field);
237	          }
238	          card.append(title, description, badge, fields);
239	          list.append(card);
240	        }
241	      } catch (error) {
242	        status.textContent = `数据目录暂时不可用：${error.message}`;
243	      }
244	    }
245	
246	    async function refreshBudget() {
247	      try {
248	        const response = await fetch('/api/privacy-budget');
249	        if (!response.ok) throw new Error(`HTTP ${response.status}`);
250	        const budget = await response.json();
251	        document.getElementById('budget-initial').textContent = budget.initial_budget;
252	        document.getElementById('budget-used').textContent = budget.used_budget;
253	        document.getElementById('budget-remaining').textContent = budget.remaining_budget;
254	      } catch (error) {
255	        for (const key of ['initial', 'used', 'remaining']) {
256	          document.getElementById(`budget-${key}`).textContent = '不可用';
257	        }
258	      }
259	    }
260	
261	    function describeFilters(filters) {
262	      const entries = Object.entries(filters || {});
263	      if (!entries.length) return '（无筛选）';
264	      return entries.map(([field, value]) => `${field}=${value}`).join('，');
265	    }
266	
267	    async function refreshHistory() {
268	      const container = document.getElementById('releases');
269	      try {
270	        const response = await fetch('/api/releases');
271	        if (!response.ok) throw new Error(`HTTP ${response.status}`);
272	        const releases = await response.json();
273	        container.textContent = '';
274	        if (!releases.length) {
275	          const empty = document.createElement('p');
276	          empty.className = 'empty';
277	          empty.textContent = '暂无发布记录。';
278	          container.append(empty);
279	          return;
280	        }
281	        for (const release of releases) {
282	          const card = document.createElement('article');
283	          card.className = 'release-card';
284	          const title = document.createElement('h3');
285	          title.textContent = `发布计数 ${release.published_count}`;
286	          const details = document.createElement('dl');
287	          const items = [
288	            ['筛选条件', describeFilters(release.filters)],
289	            ['ε', release.epsilon],
290	            ['剩余预算', release.remaining_budget],
291	            ['发布时间', new Date(release.created_at).toLocaleString()],
292	            ['request_id', release.request_id],
293	            ['release_id', release.release_id],
294	          ];
295	          for (const [label, value] of items) {
296	            const dt = document.createElement('dt');
297	            dt.textContent = label;
298	            const dd = document.createElement('dd');
299	            dd.textContent = value;
300	            details.append(dt, dd);
301	          }
302	          card.append(title, details);
303	          container.append(card);
304	        }
305	      } catch (error) {
306	        container.textContent = `发布历史暂时不可用：${error.message}`;
307	      }
308	    }
309	
310	    function formatError(data, status) {
311	      if (data && typeof data.detail === 'string') return data.detail;
312	      if (data && Array.isArray(data.detail)) {
313	        return data.detail
314	          .map(item => `${(item.loc || []).filter(part => part !== 'body').join('.')}: ${item.msg}`)
315	          .join('；');
316	      }
317	      return `请求失败（HTTP ${status}）`;
318	    }
319	
320	    document.getElementById('release-form').addEventListener('submit', async (event) => {
321	      event.preventDefault();
322	      const message = document.getElementById('release-message');
323	      const button = document.getElementById('publish-button');
324	      const filters = {};
325	      for (const field of FILTER_FIELDS) {
326	        const value = document.getElementById(`filter-${field}`).value.trim();
327	        if (value) filters[field] = value;
328	      }
329	      const payload = {
330	        request_id: document.getElementById('request-id').value.trim(),
331	        dataset_id: 'retail-demo',
332	        filters: Object.keys(filters).length ? filters : null,
333	        epsilon: parseFloat(document.getElementById('epsilon').value),
334	      };
335	      message.className = '';
336	      message.textContent = '';
337	      button.disabled = true;
338	      try {
339	        const response = await fetch('/api/releases', {
340	          method: 'POST',
341	          headers: { 'Content-Type': 'application/json' },
342	          body: JSON.stringify(payload),
343	        });
344	        const data = await response.json().catch(() => null);
345	        if (!response.ok) {
346	          message.className = 'error';
347	          message.textContent = `发布失败：${formatError(data, response.status)}`;
348	          return;
349	        }
350	        message.className = 'success';
351	        message.textContent = `已发布计数 ${data.published_count}（剩余预算 ${data.remaining_budget}）。`;
352	        document.getElementById('request-id').value = newRequestId();
353	        await Promise.all([refreshBudget(), refreshHistory()]);
354	      } catch (error) {
355	        message.className = 'error';
356	        message.textContent = `发布失败：${error.message}`;
357	      } finally {
358	        button.disabled = false;
359	      }
360	    });
361	
362	    document.getElementById('request-id').value = newRequestId();
363	
364	    const batchIdInput = document.getElementById('batch-id');
365	    const batchRequestsInput = document.getElementById('batch-requests');
366	    const batchMessage = document.getElementById('batch-message');
367	    const batchResult = document.getElementById('batch-result');
368	
369	    function exampleBatchRequests() {
370	      const suffix1 = crypto.randomUUID ? crypto.randomUUID().slice(0, 8) : String(Date.now());
371	      const suffix2 = crypto.randomUUID ? crypto.randomUUID().slice(-8) : String(Date.now() + 1);
372	      return [
373	        { request_id: `req-${suffix1}`, dataset_id: 'retail-demo', filters: { region: 'north' }, epsilon: 0.3 },
374	        { request_id: `req-${suffix2}`, dataset_id: 'retail-demo', filters: null, epsilon: 0.2 },
375	      ];
376	    }
377	
378	    function fillBatchExample() {
379	      batchIdInput.value = `batch-${crypto.randomUUID ? crypto.randomUUID().slice(0, 8) : Date.now()}`;
380	      batchRequestsInput.value = JSON.stringify(exampleBatchRequests(), null, 2);
381	    }
382	
383	    document.getElementById('batch-example-button').addEventListener('click', fillBatchExample);
384	    fillBatchExample();
385	
386	    function renderBatchResult(data, replayed) {
387	      batchResult.textContent = '';
388	      const summary = document.createElement('div');
389	      summary.className = 'batch-summary';
390	      summary.textContent = `${replayed ? '重放首次响应（未采样、未扣费）' : '整批已提交'} · ${data.releases.length} 条 · 合计 ε=${data.total_epsilon} · 最终剩余预算 ${data.remaining_budget} · ${new Date(data.created_at).toLocaleString()}`;
391	      batchResult.append(summary);
392	      data.releases.forEach((release, index) => {
393	        const card = document.createElement('div');
394	        card.className = 'batch-item';
395	        const head = document.createElement('div');
396	        head.className = 'batch-item-head';
397	        const order = document.createElement('strong');
398	        order.textContent = `#${index + 1} 计数 ${release.published_count}`;
399	        const rid = document.createElement('span');
400	        rid.className = 'muted';
401	        rid.textContent = `request_id=${release.request_id}`;
402	        const filters = document.createElement('span');
403	        filters.className = 'muted';
404	        filters.textContent = describeFilters(release.filters);
405	        const eps = document.createElement('span');
406	        eps.className = 'muted';
407	        eps.textContent = `ε=${release.epsilon}，扣后余额 ${release.remaining_budget}`;
408	        head.append(order, rid, filters, eps);
409	        card.append(head);
410	        batchResult.append(card);
411	      });
412	    }
413	
414	    document.getElementById('batch-form').addEventListener('submit', async (event) => {
415	      event.preventDefault();
416	      const button = document.getElementById('batch-publish-button');
417	      batchMessage.className = '';
418	      batchMessage.textContent = '';
419	      batchResult.textContent = '';
420	      const batchId = batchIdInput.value.trim();
421	      let requests;
422	      try {
423	        requests = JSON.parse(batchRequestsInput.value);
424	      } catch (error) {
425	        batchMessage.className = 'error';
426	        batchMessage.textContent = `批量发布失败：requests 不是合法 JSON（${error.message}）。`;
427	        return;
428	      }
429	      if (!Array.isArray(requests) || requests.length < 1 || requests.length > 20) {
430	        batchMessage.className = 'error';
431	        batchMessage.textContent = '批量发布失败：requests 必须是包含 1–20 项的 JSON 数组。';
432	        return;
433	      }
434	      if (!batchId) {
435	        batchMessage.className = 'error';
436	        batchMessage.textContent = '批量发布失败：batch_id 必须是非空字符串。';
437	        return;
438	      }
439	      const payload = { batch_id: batchId, requests };
440	      button.disabled = true;
441	      try {
442	        const response = await fetch('/api/releases/batch', {
443	          method: 'POST',
444	          headers: { 'Content-Type': 'application/json' },
445	          body: JSON.stringify(payload),
446	        });
447	        const data = await response.json().catch(() => null);
448	        if (!response.ok) {
449	          batchMessage.className = 'error';
450	          batchMessage.textContent = `批量发布失败：${formatError(data, response.status)}`;
451	          return;
452	        }
453	        batchMessage.className = 'success';
454	        batchMessage.textContent = response.status === 200
455	          ? '该 batch_id 已提交过，返回首次响应。'
456	          : '整批发布成功。';
457	        renderBatchResult(data, response.status === 200);
458	        await Promise.all([refreshBudget(), refreshHistory()]);
459	      } catch (error) {
460	        batchMessage.className = 'error';
461	        batchMessage.textContent = `批量发布失败：${error.message}`;
462	      } finally {
463	        button.disabled = false;
464	      }
465	    });
466	
467	    loadCatalog();
468	    refreshBudget();
469	    refreshHistory();
