471	    function localInputToIso(value) {
472	      if (!value) return '';
473	      return new Date(value).toISOString();
474	    }
475	
476	    document.getElementById('export-form').addEventListener('submit', async (event) => {
477	      event.preventDefault();
478	      const message = document.getElementById('export-message');
479	      const button = document.getElementById('export-button');
480	      const params = new URLSearchParams();
481	      params.set('format', document.getElementById('export-format').value);
482	      const datasetId = document.getElementById('export-dataset').value;
483	      if (datasetId) params.set('dataset_id', datasetId);
484	      const requestId = document.getElementById('export-request-id').value.trim();
485	      if (requestId) params.set('request_id', requestId);
486	      const fromIso = localInputToIso(document.getElementById('export-from').value);
487	      const toIso = localInputToIso(document.getElementById('export-to').value);
488	      if (fromIso) params.set('from', fromIso);
489	      if (toIso) params.set('to', toIso);
