document.getElementById('share-status-filter').addEventListener('change', loadManagedShares);
document.getElementById('share-refresh-button').addEventListener('click', loadManagedShares);
loadManagedShares();

const OUTCOME_LABELS = {
  served: '成功',
  expired: '已过期',
  revoked: '已撤销',
  superseded: '旧代令牌',
};

document.getElementById('audit-form').addEventListener('submit', async (event) => {
  event.preventDefault();
  const message = document.getElementById('audit-message');
  const container = document.getElementById('audit-events');
  const button = document.getElementById('audit-button');
  const params = new URLSearchParams();
  const shareId = document.getElementById('audit-share-id').value.trim();
  if (shareId) params.set('share_id', shareId);
  const outcome = document.getElementById('audit-outcome').value;
  if (outcome) params.set('outcome', outcome);
  const fromIso = localInputToIso(document.getElementById('audit-from').value);
  const toIso = localInputToIso(document.getElementById('audit-to').value);
  if (fromIso) params.set('from', fromIso);
  if (toIso) params.set('to', toIso);
  const limitRaw = document.getElementById('audit-limit').value;
  const limit = Number.parseInt(limitRaw, 10);
  message.className = '';
  message.textContent = '';
  container.textContent = '';
  if (limitRaw === '' || !Number.isInteger(limit) || limit < 1 || limit > 100) {
    message.className = 'error';
    message.textContent = '查询失败：limit 必须是 1–100 的整数。';
    return;
  }
  params.set('limit', String(limit));
  if (fromIso && toIso && new Date(fromIso) >= new Date(toIso)) {
    message.className = 'error';
    message.textContent = '查询失败：起始时间必须早于结束时间。';
    return;
  }
  button.disabled = true;
  try {
    const response = await fetch(`/api/share-access-events?${params.toString()}`);
    const data = await response.json().catch(() => null);
    if (!response.ok) {
      message.className = 'error';
      message.textContent = `查询失败：${formatError(data, response.status)}`;
      return;
    }
    if (!data.length) {
      message.className = '';
      message.textContent = '没有匹配的访问事件。';
      return;
    }
    message.className = 'success';
    message.textContent = `共 ${data.length} 条访问事件（按访问时间倒序）。`;
    for (const item of data) {
      const card = document.createElement('article');
      card.className = 'release-card';
      const title = document.createElement('h3');
      const badge = document.createElement('span');
      badge.className = 'status-badge ' + (
        item.outcome === 'served' ? 'status-active' : 'status-revoked'
      );
      badge.textContent = `${item.outcome}（${OUTCOME_LABELS[item.outcome] || item.outcome}）`;
      title.append('访问事件 ', badge);
      const details = document.createElement('dl');
      const items = [
        ['访问时间', new Date(item.accessed_at).toLocaleString()],
        ['返回条数', item.result_count],
        ['令牌代次', `第 ${item.token_version} 代`],
        ['share_id', item.share_id],
        ['event_id', item.event_id],
      ];
      for (const [label, value] of items) {
        const dt = document.createElement('dt');
        dt.textContent = label;
        const dd = document.createElement('dd');
        dd.textContent = value;
        details.append(dt, dd);
      }
      card.append(title, details);
      container.append(card);
    }
  } catch (error) {
    message.className = 'error';
    message.textContent = `查询失败：${error.message}`;
  } finally {
    button.disabled = false;
  }
});

